// ═══════════════════════════════════════════════════════════
//  PHASE 2: Deduplicate and insert
// ═══════════════════════════════════════════════════════════

console.log(`\n=== PHASE 2: Deduplicating ${NEW_PAPERS.length} candidate papers ===\n`);

const insertStmt = db.prepare(`
  INSERT OR IGNORE INTO case_studies (id, source, domain, title, problem, solution, abstract_pattern, keywords_json, url)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
`);

let inserted = 0;
let skipped = 0;

const insertTx = db.transaction(() => {
  for (const p of NEW_PAPERS) {
    const titleLower = p.t.toLowerCase();
    if (existingIds.has(p.id) || existingTitles.has(titleLower)) {
      skipped++;
      continue;
    }
    insertStmt.run(
      p.id,
      p.u && p.u.includes("arxiv") ? "ArXiv" : "Peer-Reviewed Journal",
      p.d,
      p.t,
      p.p,
      p.s,
      p.ap,
      JSON.stringify(p.kw),
      p.u
    );
    existingIds.add(p.id);
    existingTitles.add(titleLower);
    inserted++;
  }
});
insertTx();

console.log(`  ✅ Inserted: ${inserted}`);
console.log(`  ⏭️  Skipped (duplicate): ${skipped}`);

// ═══════════════════════════════════════════════════════════
//  PHASE 3: Rebuild FTS5 index
// ═══════════════════════════════════════════════════════════

console.log(`\n=== PHASE 3: Rebuilding FTS5 index ===\n`);
try {
  db.exec(`INSERT INTO case_studies_fts(case_studies_fts) VALUES('rebuild')`);
  console.log("  ✅ FTS5 index rebuilt successfully");
} catch (err) {
  console.warn("  ⚠️  FTS5 rebuild warning:", err.message);
}

